"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0967-01-01:0":{"b": ["Washmgîr sterft tijdens de jacht (357/967).", "68f9525b"], "d": ["Washmgîr sterft tijdens de jacht (357/967).", "68f9525b"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0972-07-01:0":{"b": ["Hasan al-A‘sam bezet Ramla opnieuw en verslaat een sterk Fatimidisch leger", "c3b5ad80"], "d": ["De Qarmatische leider Hasan al-A‘sam bezette in Ramadan 361 (juli 972) Ramla opnieuw en versloeg een sterk Fatimidisch leger; een jaar later viel hij over land en zee Egypte aan en belegerde Caïro opnieuw maar werd verslagen door Azîz-Billâh.", "f629e2e1"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0981-01-01:0":{"b": ["De Chinese gezant Wang Yande begint zijn reis onder de Oeigoeren (981-984); zijn verslag is de belangrijkste bron over de Oeigoerse cultuur van Turfan.", "478d801b"], "d": ["De Chinese gezant Wang Yande begint zijn reis onder de Oeigoeren (981-984); zijn verslag is de belangrijkste bron over de Oeigoerse cultuur van Turfan.", "478d801b"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0985-01-01:0":{"b": ["Het leger dat Mansûr b. Bulukkîn naar Fez en Sijilmâsa stuurde, mislukt (374, 985).", "85a5064b"], "d": ["Het leger dat Mansûr b. Bulukkîn naar Fez en Sijilmâsa stuurde, mislukt (374, 985).", "85a5064b"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0985-05-24:0":{"b": ["De Qarmaten van Bahrein bezetten Kufa twee jaar na Basra; ze kunnen zich niet handhaven tegenover de Buyiden en trekken zich terug", "4b76d4b0"], "d": ["Na de dood van de Buyide Adud al-Dawla (372/983) vielen de Qarmaten van Bahrein, die hun kracht in Zuid-Irak wilden tonen, in 373 (983-84) Basra aan en maakten het schatplichtig en bezetten twee jaar later Kufa; maar ze konden zich tegenover de Buyiden niet handhaven, trokken zich terug en hadden in Irak geen woord meer mee te spreken.", "0451dba6"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0991-01-01:0":{"b": ["Abû al-Fath Muhammad b. Annâz begint in Hulwân te regeren", "b1809519"], "d": ["Abû al-Fath Muhammad b. Annâz begint in Hulwân te regeren", "b1809519"]},
