"OLAYLAR_ORTACAG_ORTADOGU:0910-01-15:0":{"b": ["Abû Abdullah trekt samen met Ubaydullah al-Mahdî Raqqâda binnen; het Fatimidische imamaat begint feitelijk", "cf944741"], "d": ["Abû Abdullah nam Raqqâda, de hoofdstad van de Aghlabiden, in en verdreef de laatste emir Ziyâdetullah (296/909); op 29 Rabî‘ al-âkhir 297 (15 januari 910) trok hij samen met Ubaydullah Raqqâda binnen.", "99f93307"]},
"OLAYLAR_ORTACAG_ORTADOGU:0915-07-17:0":{"b": ["Ubaydullah al-Mahdî sticht de stad Mahdia", "f6aef126"], "d": ["Mahdî stichtte de stad Mahdia op een schiereiland aan de kust van Oost-Ifrîqiya (303/915).", "eccb119a"]},
"OLAYLAR_ORTACAG_ORTADOGU:0920-05-23:0":{"b": ["Mahdia wordt uitgeroepen tot Fatimidische hoofdstad", "a160b592"], "d": ["Vijf jaar na de stichting werd Mahdia tot hoofdstad uitgeroepen (308/920).", "eb88ec52"]},
"OLAYLAR_ORTACAG_ORTADOGU:0929-03-02:0":{"b": ["Abu al-Hayjâ sterft; de dynastie splitst zich in een tak van Mosul en een van Aleppo, in Mosul treedt Nâsir al-Dawla Hasan op de voorgrond", "2ecf5e83"], "d": ["Abu al-Hayjâ sterft; de dynastie splitst zich in een tak van Mosul en een van Aleppo, in Mosul treedt Nâsir al-Dawla Hasan op de voorgrond", "2ecf5e83"]},
"OLAYLAR_ORTACAG_ORTADOGU:0930-01-12:0":{"b": ["De Qarmaten bezetten Mekka en voeren de Zwarte Steen naar Ahsâ (Lahsâ); de Qarmatische staat van Bahrein als eigenaar van Lahsâ in de eerste gedateerde getuigenis", "5ca42bf9"], "d": ["De Ismâ‘îlitische Qarmaten (Qarmatische staat van Bahrein) bezetten Mekka in 317 H / 929 en voerden de Zwarte Steen naar Ahsâ (Lahsâ); twintig jaar later werd hij echter teruggeplaatst. In de atlas wordt Lahsâ, dat eerder tot het Abbasidische kalifaat behoorde, vanaf deze eerste gedateerde getuigenis aan de Qarmaten toegeschreven.", "a6a3faa1"]},
